static inline int16_t distortion_curveSample16(const Distortion *dist,
										const int16_t in)
{
	float x = in/32767.f;
	x = dist->out_gain*x/(1+dist->shape*fabsf(x));
	return (int16_t)(int32_t)(x*32767);
}

